package ru.local.jarvis;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import android.view.View;
/** Native arc-reactor visualization. No microphone capture or WebView in the view. */
public final class ReactorView extends View {
 final Paint stroke=new Paint(3),glow=new Paint(3),core=new Paint(3);final RectF outer=new RectF(),middle=new RectF(),inner=new RectF();final float[] marks=new float[240];float cx,cy,radius,energy;boolean active;
 public ReactorView(Context context){super(context);setContentDescription("Голосовой реактор Джарвиса");stroke.setStyle(Paint.Style.STROKE);stroke.setStrokeCap(Paint.Cap.ROUND);}
 public void setActive(boolean value){active=value;if(value)invalidate();}
 protected void onSizeChanged(int w,int h,int oldw,int oldh){cx=w/2f;cy=h/2f;radius=Math.min(w,h)*.40f;outer.set(cx-radius,cy-radius,cx+radius,cy+radius);middle.set(cx-radius*.79f,cy-radius*.79f,cx+radius*.79f,cy+radius*.79f);inner.set(cx-radius*.59f,cy-radius*.59f,cx+radius*.59f,cy+radius*.59f);glow.setShader(new RadialGradient(cx,cy,radius*1.18f,new int[]{0x009d39ff,0x109d39ff,0x509d39ff,0x009d39ff},new float[]{0,.60f,.84f,1},Shader.TileMode.CLAMP));core.setShader(new RadialGradient(cx,cy,radius*.48f,new int[]{0xfff3ffff,0xd391f1ff,0x487943df,0x007943df},new float[]{0,.32f,.72f,1},Shader.TileMode.CLAMP));for(int n=0;n<60;n++){double angle=n*Math.PI/30;float start=radius*.93f,end=radius*(n%5==0?1.03f:.98f);marks[n*4]=cx+(float)Math.sin(angle)*start;marks[n*4+1]=cy+(float)Math.cos(angle)*start;marks[n*4+2]=cx+(float)Math.sin(angle)*end;marks[n*4+3]=cy+(float)Math.cos(angle)*end;}}
 protected void onDraw(Canvas canvas){if(radius<=0)return;float target=Assistant.speaking?Assistant.voiceEnergy:Assistant.capturing?Assistant.micEnergy:0;energy+=(target-energy)*.22f;float seconds=(SystemClock.uptimeMillis()%600000)/1000f;float breathing=(float)Math.sin(seconds*1.6)*.008f;int saved=canvas.save();canvas.scale(1+breathing+energy*.065f,1+breathing+energy*.065f,cx,cy);glow.setAlpha(145+(int)(energy*95));canvas.drawCircle(cx,cy,radius*1.18f,glow);core.setAlpha(175+(int)(energy*80));canvas.drawCircle(cx,cy,radius*.48f,core);stroke.setStrokeWidth(Math.max(1,radius*.009f));stroke.setColor(0x779d55f1);canvas.drawCircle(cx,cy,radius*.89f,stroke);canvas.drawLines(marks,stroke);drawRing(canvas,outer,seconds*24,220,0xcccc63ff,.019f);drawRing(canvas,middle,-seconds*35,140,0xffb054ff,.025f);drawRing(canvas,middle,180-seconds*35,140,0xb978ddff,.015f);drawRing(canvas,inner,seconds*49,255,0xd07ce5ff,.012f);stroke.setStrokeWidth(radius*.008f);stroke.setColor(0x99d9f9ff);canvas.drawCircle(cx,cy,radius*.43f,stroke);canvas.restoreToCount(saved);if(active&&getWindowVisibility()==VISIBLE)postInvalidateDelayed(33);}
 void drawRing(Canvas canvas,RectF rect,float angle,float sweep,int color,float width){stroke.setColor(color);stroke.setStrokeWidth(radius*(width+energy*.008f));canvas.drawArc(rect,angle,sweep,false,stroke);}
}
